+    TilingInfo tilingInfo;
+    EXPECT_TRUE(ExecuteTiling(tilingContextPara, tilingInfo));
+    EXPECT_EQ(GetIsInt32FromTilingKey(tilingInfo.tilingKey), 0); // lenSrcH超 INT32_MAX 必走 int64
 }
